### 2. CDC Consumer Flow - Complete Call Chain

Here's the **CRITICAL FINDING**: The legacy sync modules are **NOT currently included** in the dynamic-indexer bootstrap module's dependencies or scan packages.

#### 2.1 Kafka Consumer Entry Points

**Three Kafka listeners** are configured in `/Users/admin/project/integrated-search/inbound-adapter/handler/src/main/kotlin/com/cowave/search/inbound_adapter/handler/config/DynamicIndexConfig.kt`:

1. **Product CDC Consumer**: `ProductDynamicIndexListener`
   - Consumes from topic: `cmn-search-team.search.product.refine.v2`
   - Group ID: `cmn-search-team-group-dynamic-indexer`

2. **Catalog CDC Consumer**: `CatalogDynamicIndexListener`
   - Consumes from topic: `cmn-search-team.search.catalog.refine.v2`
   - Group ID: `cmn-search-team-group-dynamic-indexer`

3. **Admin Consumer**: `DynamicIndexAdminListener`
   - Consumes from topic: `cmn-search-team.search.index.admin.v1`
   - Handles offset seeking/rewinding

#### 2.2 Product CDC Flow (Where Legacy Sync Happens)

**File**: `/Users/admin/project/integrated-search/inbound-adapter/handler/src/main/kotlin/com/cowave/search/inbound_adapter/handler/listener/ProductDynamicIndexListener.kt`

```kotlin
class ProductDynamicIndexListener(
    private val productIndexApplicationService: ProductIndexApplicationService,
    groupId: String,
    consumerCallbackManager: ConsumerCallbackManager,
) : FlinkCdcBatchListener(groupId, consumerCallbackManager),
    BatchAcknowledgingConsumerAwareMessageListener<SpecificRecord, SpecificRecord> {

    override fun onMessage(
        data: List<ConsumerRecord<SpecificRecord, SpecificRecord>>,
        acknowledgment: Acknowledgment?,
        consumer: Consumer<*, *>,
    ) {
        runCatching {
            val changedDocuments = data
                .filter { record ->
                    val envelope = record.value() as ProductCdcEnvelope
                    val product = envelope.after ?: envelope.before
                    product != null && product.categoryId > 0
                }.map { it.toChangedProductData() }

            // THIS IS THE KEY CALL - goes to application service
            productIndexApplicationService.indexProducts(changedDocuments)
        }.onSuccess {
            acknowledgment?.acknowledge()
            rewindIfNeeded()
        }.onFailure { ex ->
            logger.error(ex) { "Failed to index products" }
        }.getOrThrow()
    }
}
```

**Mapping Function**: `/Users/admin/project/integrated-search/inbound-adapter/handler/src/main/kotlin/com/cowave/search/inbound_adapter/handler/mapper/ChangeDataMapper.kt`

```kotlin
fun ConsumerRecord<SpecificRecord, SpecificRecord>.toChangedProductData(): ChangedData<Product> {
    val key = this.key() as ProductCdcKey
    val value = this.value() as ProductCdcEnvelope

    return ChangedData(
        id = (key.`id$1` ?: value.after?.`id$1` ?: value.before?.`id$1`!!).toString(),
        op = convertOp(value.op),  // "c", "u", "d" -> CREATE, UPDATE, DELETE
        beforeData = value.before,
        afterData = value.after,
        partition = this.partition(),
        offset = this.offset(),
    )
}
```

---

### 3. Legacy Sync Entry Point and Call Chain

**File**: `/Users/admin/project/integrated-search/application/index/src/main/kotlin/com/cowave/search/application/index/service/ProductIndexApplicationService.kt`

This is where **BOTH indexing and legacy sync happen**:

```kotlin
@Service
class ProductIndexApplicationService(
    private val productIndexRepository: ProductIndexRepository,
    private val productAssembleService: ProductAssembleService,
    private val legacySyncApplicationService: LegacySyncApplicationService,  // <-- INJECTED
) {

    fun indexProducts(changedData: List<ChangedData<Product>>): IndexResult {
        val merged = changedData.let(ProductMergeStrategy::merge)

        // 레거시 역싱크: merge 후, assemble 전에 실행 (실패해도 ES 색인은 진행)
        runCatching {
            val legacyData = LegacySyncMapper.toChangedLegacyData(merged)
            legacySyncApplicationService.syncToLegacy(legacyData)  // <-- LEGACY SYNC CALL
        }.onFailure { ex ->
            logger.error(ex) { "Legacy sync failed, proceeding with ES indexing" }
        }

        // Elasticsearch indexing continues regardless of legacy sync success
        val indexDocuments = merged
            .let { productAssembleService.assemble(it) }
            .filter(ProductEvaluator::evaluate)

        return productIndexRepository.bulk(indexDocuments)
    }
}
```

**Key Points**:
- Legacy sync happens **AFTER merge, BEFORE assemble**
- Legacy sync is wrapped in `runCatching` - **failures do NOT block ES indexing**
- The data is transformed from `Product` to `LegacyProductData` via `LegacySyncMapper.toChangedLegacyData()`

---

### 4. LegacySyncApplicationService Details

**File**: `/Users/admin/project/integrated-search/application/index/src/main/kotlin/com/cowave/search/application/index/service/LegacySyncApplicationService.kt`

```kotlin
@Service
@ConditionalOnProperty(name = ["legacy-sync.enabled"], havingValue = "true", matchIfMissing = true)
class LegacySyncApplicationService(
    private val legacySyncRepository: LegacySyncRepository,
    private val categoryApplicationService: CategoryApplicationService,
    private val mallApplicationService: MallApplicationService,
) {

    fun syncToLegacy(changedData: List<ChangedData<LegacyProductData>>) {
        if (changedData.isEmpty()) return

        // Fetch category and mall data for mapping
        val categoryIds = changedData
            .flatMap { listOfNotNull(it.afterData?.categoryId, it.beforeData?.categoryId) }
            .distinct()
        val mallIds = changedData
            .flatMap { listOfNotNull(it.afterData?.shopId, it.beforeData?.shopId) }
            .distinct()

        val categories = if (categoryIds.isNotEmpty()) 
            categoryApplicationService.getCachedAllByIds(categoryIds) else emptyMap()
        val malls = if (mallIds.isNotEmpty()) 
            mallApplicationService.getCachedAllByIds(mallIds) else emptyMap()

        val grouped = changedData.groupBy { it.op }

        grouped.forEach { (op, items) ->
            val linked = mutableListOf<LinkedProductRequest>()
            val unlinked = mutableListOf<UnlinkedProductRequest>()
            val unlinkedDeletes = mutableListOf<UnlinkedProductDeleteRequest>()

            items.forEach items@{ item ->
                val data = if (op == Operation.DELETE) item.beforeData else item.afterData
                if (data == null) {
                    logger.warn { "Legacy sync skipped: no data for product id=${item.id}, op=$op" }
                    return@items
                }

                val mall = malls[data.shopId]

                when {
                    // Matched products (PDM) - CREATE/UPDATE/DELETE all
                    data.isCatalogMatch -> {
                        linked.add(LegacySyncMapper.toLinkedRequest(data, mall))
                    }
                    // Unmatched DELETE - simplified request
                    op == Operation.DELETE -> {
                        unlinkedDeletes.add(LegacySyncMapper.toUnlinkedDeleteRequest(data, mall))
                    }
                    // Unmatched CREATE/UPDATE - full fields
                    else -> {
                        val category = categories[data.categoryId]
                        unlinked.add(LegacySyncMapper.toUnlinkedRequest(data, category, mall))
                    }
                }
            }

            // Push to legacy system via repository
            if (linked.isNotEmpty()) legacySyncRepository.pushLinkedProducts(linked, op)
            if (unlinked.isNotEmpty()) legacySyncRepository.pushUnlinkedProducts(unlinked, op)
            if (unlinkedDeletes.isNotEmpty()) legacySyncRepository.pushUnlinkedProductDeletes(unlinkedDeletes)
        }
    }
}
```

**Method Signature**: `fun syncToLegacy(changedData: List<ChangedData<LegacyProductData>>)`

**Service Logic**:
1. Fetches category and mall metadata (for both beforeData and afterData to handle DELETEs)
2. Groups changes by operation (CREATE, UPDATE, DELETE)
3. Classifies products into:
   - **Linked products** (catalog-matched, `isCatalogMatch=true`) → PDM service
   - **Unlinked products** (non-matched, CREATE/UPDATE) → TCMPNY_LINK service
   - **Unlinked deletes** (non-matched, DELETE) → TCMPNY_LINK service (simplified payload)

---

### 5. Repository Implementation - HTTP API Calls

**Interface**: `/Users/admin/project/integrated-search/application/index/src/main/kotlin/com/cowave/search/application/index/repository/LegacySyncRepository.kt`

```kotlin
interface LegacySyncRepository {
    fun pushLinkedProducts(products: List<LinkedProductRequest>, operation: Operation)
    fun pushUnlinkedProducts(products: List<UnlinkedProductRequest>, operation: Operation)
    fun pushUnlinkedProductDeletes(products: List<UnlinkedProductDeleteRequest>)
}
```

**Implementation**: `/Users/admin/project/integrated-search/outbound-adapter/legacy/src/main/kotlin/com/cowave/search/outbound_adapter/legacy/LegacySyncRepositoryImpl.kt`

```kotlin
@Component
class LegacySyncRepositoryImpl(
    private val legacyApiClient: LegacyApiClient,
    private val objectMapper: ObjectMapper,
) : LegacySyncRepository {

    override fun pushLinkedProducts(products: List<LinkedProductRequest>, operation: Operation) {
        val body = objectMapper.writeValueAsString(products)
        val method = operation.toHttpMethod()
        logger.info { "레거시 연동상품 동기화 요청 [operation=$operation, count=${products.size}]" }
        legacyApiClient.pushQueue(service = "PDM", method = method, body = body)
    }

    override fun pushUnlinkedProducts(products: List<UnlinkedProductRequest>, operation: Operation) {
        val body = objectMapper.writeValueAsString(products)
        val method = operation.toHttpMethod()
        logger.info { "레거시 비연동상품 동기화 요청 [operation=$operation, count=${products.size}]" }
        legacyApiClient.pushQueue(service = "TCMPNY_LINK", method = method, body = body)
    }

    override fun pushUnlinkedProductDeletes(products: List<UnlinkedProductDeleteRequest>) {
        val body = objectMapper.writeValueAsString(products)
        logger.info { "레거시 비연동상품 삭제 동기화 요청 [count=${products.size}]" }
        legacyApiClient.pushQueue(service = "TCMPNY_LINK", method = HttpMethod.DELETE, body = body)
    }

    private fun Operation.toHttpMethod(): HttpMethod = when (this) {
        Operation.CREATE -> HttpMethod.POST
        Operation.UPDATE -> HttpMethod.PUT
